# ---------------------------------------------------------------- L-AH04 외국어 배정 (조건 추론, 216가지 전수 조사, 반드시 참)
LG = ['영어', '중국어', '일본어', '프랑스어']
PPL = ['甲', '乙', '丙']
def ok4(m):
    return (all(any(l in m[p_] for p_ in PPL) for l in LG) and not (m['甲'] & m['乙']) and all(('중국어' not in m[p_]) or ('일본어' in m[p_]) for p_ in PPL)
            and '영어' not in m['丙'] and sum('프랑스어' in m[p_] for p_ in PPL) == 1)
S4 = [m for m in (dict(zip(PPL, map(set, c))) for c in itertools.product(itertools.combinations(LG, 2), repeat=3)) if ok4(m)]
check(sorted(tuple(sorted(m[p_]) for p_ in PPL) for m in S4) == sorted([(sorted({'영어', '프랑스어'}), sorted({'중국어', '일본어'}), sorted({'중국어', '일본어'})), (sorted({'중국어', '일본어'}), sorted({'영어', '프랑스어'}), sorted({'중국어', '일본어'}))]), f'L-AH04 {S4}')
f4 = [all('영어' in m['甲'] for m in S4), all('일본어' in m['乙'] for m in S4), all(sum('일본어' in m[p_] for p_ in PPL) == 1 for m in S4),
      all([p_ for p_ in PPL if '영어' in m[p_]] != [p_ for p_ in PPL if '프랑스어' in m[p_]] for m in S4), all('중국어' in m['丙'] for m in S4)]
one_true(f4, 4, 'L-AH04')
COMB4 = [set(c) for c in itertools.combinations(LG, 2) if '중국어' not in c or '일본어' in c]
check(sorted(map(sorted, COMB4)) == sorted(map(sorted, [{'영어', '일본어'}, {'영어', '프랑스어'}, {'일본어', '프랑스어'}, {'중국어', '일본어'}])) and [sorted(a | b) for a, b in itertools.combinations(COMB4, 2) if not a & b] == [sorted(set(LG))] and all(m['丙'] == {'중국어', '일본어'} for m in S4), 'L-AH04 explanation steps')
check(any('영어' not in m['甲'] for m in S4) and any('일본어' not in m['乙'] for m in S4) and all(sum('일본어' in m[p_] for p_ in PPL) == 2 for m in S4), 'L-AH04 counterexamples')
